define("mod_readingassessment/post_coach", [], function() {
    'use strict';

    function init(config) {
        if (!Array.isArray(config.words) || config.words.length === 0) {
            return;
        }

        var wordsParam = encodeURIComponent(config.words.join(','));
        var url = config.coachUrl + '?cmid=' + window.PT_CMID + '&hideheader=1&words=' + wordsParam;

        if (!document.getElementById('pt-coach-iframe-modal')) {
            var html = [
                '<div class="modal fade" id="pt-coach-iframe-modal" tabindex="-1" role="dialog" aria-hidden="true">',
                '  <div class="modal-dialog modal-lg" role="document">',
                '    <div class="modal-content">',
                '      <div class="modal-header bg-primary text-white">',
                '        <h5 class="modal-title">🎙️ Pronunciation Coach</h5>',
                '        <button type="button" class="close text-white" data-dismiss="modal" aria-label="Close">',
                '          <span aria-hidden="true">&times;</span>',
                '        </button>',
                '      </div>',
                '      <div class="modal-body p-0" style="height: 600px;">',
                '        <iframe id="pt-coach-iframe" allow="microphone; autoplay" src="" style="width: 100%; height: 100%; border: none;"></iframe>',
                '      </div>',
                '    </div>',
                '  </div>',
                '</div>'
            ].join('\n');

            var wrapper = document.createElement('div');
            wrapper.innerHTML = html;
            document.body.appendChild(wrapper.firstChild);
        }

        document.getElementById('pt-coach-iframe').src = url;
        
        // Show modal (assuming jQuery/Bootstrap is present, which Moodle provides)
        if (typeof jQuery !== 'undefined') {
            jQuery('#pt-coach-iframe-modal').modal('show');
        } else {
            var modal = document.getElementById('pt-coach-iframe-modal');
            modal.classList.add('show');
            modal.style.display = 'block';
            modal.style.background = 'rgba(0,0,0,0.5)';
            // Add close handler manually if no jQuery
            modal.querySelector('.close').onclick = function() {
                modal.classList.remove('show');
                modal.style.display = 'none';
                document.getElementById('pt-coach-iframe').src = '';
            };
        }
    }

    return {
        init: init
    };
});
